# ===================== STAGE 0  =====================
import os, sys, subprocess, importlib
for pkg in ["wfdb", "mne", "seaborn", "einops", "huggingface_hub"]:
    try: importlib.import_module(pkg)
    except ImportError: subprocess.run([sys.executable, "-m", "pip", "install", "-q", pkg], check=False)

IN_COLAB = "google.colab" in sys.modules
if IN_COLAB:
    from google.colab import drive
    drive.mount("/content/drive")
    ROOT, TMP = "/content/drive/MyDrive", "/content/tmp_raw"
else:
    ROOT, TMP = os.path.abspath("."), os.path.abspath("./tmp_raw")
DATA_BASE = os.path.join(ROOT, "QMLNet_v3")          # cached PSG data from earlier runs is reused from here
BASE = os.path.join(ROOT, "NocturNet")
DIRS = {"raw_ucd": os.path.join(DATA_BASE, "raw_ucd"), "proc_c18": os.path.join(DATA_BASE, "proc_c18"),
        "proc_ucd": os.path.join(DATA_BASE, "proc_ucd"), "dres": os.path.join(DATA_BASE, "results"),
        **{k: os.path.join(BASE, k) for k in ["fm", "checkpoints", "figures", "results", "flags"]}}
for d in list(DIRS.values()) + [TMP]: os.makedirs(d, exist_ok=True)
print("Data cache:", DATA_BASE, "\nOutputs:", BASE)
